INSERT INTO public.resources (id, title, provider, url, access_label, data) VALUES
  ('excel', 'Build confidence with spreadsheets', 'GCFGlobal', 'https://edu.gcfglobal.org/en/excel/', 'Free learning', '{"id":"excel","title":"Build confidence with spreadsheets","provider":"GCFGlobal","url":"https://edu.gcfglobal.org/en/excel/","skills":["Spreadsheets","Quantity estimation"],"format":"Lessons","language":"English","access":"Free learning","practice":"Build a small budget or material-cost worksheet. Include formulas, units and a check of your totals."}'::jsonb),
  ('stats', 'Statistics and probability', 'Khan Academy', 'https://www.khanacademy.org/math/statistics-probability', 'Free learning', '{"id":"stats","title":"Statistics and probability","provider":"Khan Academy","url":"https://www.khanacademy.org/math/statistics-probability","skills":["Statistics","Data visualisation"],"format":"Lessons","language":"English","access":"Free learning","practice":"Summarise a small public dataset with a chart, a measure of centre and a note on uncertainty."}'::jsonb),
  ('economy', 'The Economy', 'CORE Econ', 'https://www.core-econ.org/', 'Free open-access books', '{"id":"economy","title":"The Economy","provider":"CORE Econ","url":"https://www.core-econ.org/","skills":["Research","Statistics"],"format":"Textbook","language":"English","access":"Free open-access books","practice":"Choose one economic question and write a short evidence-based explanation using a chart."}'::jsonb),
  ('design', 'Graphic design foundations', 'GCFGlobal', 'https://edu.gcfglobal.org/en/beginning-graphic-design/', 'Free learning', '{"id":"design","title":"Graphic design foundations","provider":"GCFGlobal","url":"https://edu.gcfglobal.org/en/beginning-graphic-design/","skills":["Typography","Visual design"],"format":"Lessons","language":"English","access":"Free learning","practice":"Create a one-page poster, then explain your hierarchy, spacing and type choices."}'::jsonb),
  ('writing', 'Writing and research resources', 'Purdue OWL', 'https://owl.purdue.edu/owl/', 'Free reference resources', '{"id":"writing","title":"Writing and research resources","provider":"Purdue OWL","url":"https://owl.purdue.edu/owl/","skills":["Technical writing","Editing","Research","Communication"],"format":"Lessons","language":"English","access":"Free reference resources","practice":"Write a one-page report for a non-specialist. Cite sources and revise after feedback."}'::jsonb),
  ('python', 'Learn scientific computing with Python', 'freeCodeCamp', 'https://www.freecodecamp.org/learn/scientific-computing-with-python/', 'Free learning', '{"id":"python","title":"Learn scientific computing with Python","provider":"freeCodeCamp","url":"https://www.freecodecamp.org/learn/scientific-computing-with-python/","skills":["Python"],"format":"Lessons","language":"English","access":"Free learning","practice":"Build a small script that solves one repetitive task and document three test cases."}'::jsonb),
  ('sql', 'Interactive SQL lessons', 'SQLBolt', 'https://sqlbolt.com/', 'Free learning', '{"id":"sql","title":"Interactive SQL lessons","provider":"SQLBolt","url":"https://sqlbolt.com/","skills":["SQL"],"format":"Lessons","language":"English","access":"Free learning","practice":"Write queries that filter, group and join a small dataset. Explain what each result means."}'::jsonb),
  ('git', 'Pro Git', 'Git', 'https://git-scm.com/book/en/v2', 'Free online book', '{"id":"git","title":"Pro Git","provider":"Git","url":"https://git-scm.com/book/en/v2","skills":["Git"],"format":"Textbook","language":"English","access":"Free online book","practice":"Create a repository, make a branch and merge a small documented change."}'::jsonb),
  ('engineering', 'Civil and environmental engineering', 'MIT OpenCourseWare', 'https://ocw.mit.edu/search/?d=Civil%20and%20Environmental%20Engineering', 'Free course materials', '{"id":"engineering","title":"Civil and environmental engineering","provider":"MIT OpenCourseWare","url":"https://ocw.mit.edu/search/?d=Civil%20and%20Environmental%20Engineering","skills":["Drawing interpretation","Quantity estimation"],"format":"Lessons","language":"English","access":"Free course materials","practice":"Choose introductory materials, annotate a simple plan and explain assumptions. Ask a qualified mentor to check technical work."}'::jsonb),
  ('planning', 'Project management learning', 'OpenLearn', 'https://www.open.edu/openlearn/money-business/project-management', 'Free learning', '{"id":"planning","title":"Project management learning","provider":"OpenLearn","url":"https://www.open.edu/openlearn/money-business/project-management","skills":["Project planning"],"format":"Lessons","language":"English","access":"Free learning","practice":"Plan a small project with scope, milestones, dependencies and a risk register."}'::jsonb),
  ('stats-video', 'Probability explained with examples', 'Khan Academy · YouTube', 'https://www.youtube.com/watch?v=yUaI0JriZtY', 'Free video', '{"id":"stats-video","title":"Probability explained with examples","provider":"Khan Academy · YouTube","url":"https://www.youtube.com/watch?v=yUaI0JriZtY","skills":["Statistics"],"format":"Video","language":"English","access":"Free video","practice":"Solve two probability examples and explain your reasoning in plain language."}'::jsonb) ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data;
