INSERT INTO public.jobs (id, title, description, source_kind, city) VALUES
  ('site', 'Civil engineering intern', 'Example role brief, not a live vacancy. Support a site team with drawing interpretation, spreadsheets and quantity estimation. Prepare clear technical writing for site reports. Currently enrolled in a relevant engineering degree. Site safety induction and supervision required.', 'example', 'Lahore'),
  ('research', 'Economic research assistant', 'Example role brief, not a live vacancy. Support research using statistics, spreadsheets and data visualisation. Summarise findings through technical writing. Relevant undergraduate degree or current enrolment required. Familiarity with SQL is preferred.', 'example', 'Islamabad'),
  ('visual', 'Junior visual designer', 'Example role brief, not a live vacancy. Use typography and visual design to produce layouts. Show communication skills and research behind your decisions. A portfolio is required; a degree is preferred.', 'example', 'Karachi'),
  ('operations', 'Operations associate', 'Example role brief, not a live vacancy. Support operations with spreadsheets, project planning and communication. Use research to document processes. Relevant degree preferred.', 'example', 'Remote'),
  ('developer', 'Junior software developer', 'Example role brief, not a live vacancy. Build small services using Python, SQL and Git. Clear communication and documented projects are required. Relevant degree preferred.', 'example', 'Remote'),
  ('editor', 'Editorial assistant', 'Example role brief, not a live vacancy. Support research, editing and technical writing. Strong communication and a writing portfolio required.', 'example', 'Lahore') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
